function cycleCommensurability(a,b,maxA=512){
  const A=a.days, B=b.days;
  /* ── ONE ENGINE, TWO SURFACES ─────────────────────────────────────────────
     This used to expand the continued fraction inline, which made it the second
     copy of a recurrence the frequency laboratory already ran. Same question,
     same arithmetic, two implementations that nothing compared. It now CALLS
     that one: oscContFrac is the number theory, and everything below is the
     interpretation in days.
     The merge buys a distinction the cycles side did not have. oscContFrac
     records WHY the expansion stopped, and the two reasons are not the same
     fact at all: 'terminated' means the remainder reached zero and the ratio IS
     the fraction — exactly commensurate, forever — while 'cap' means only that
     the denominator grew past what we would consider. This table contains one
     of each. The Hale cycle is exactly twice the sunspot cycle because the
     magnetic polarity returns after two spot cycles, which is a definition and
     terminates; the Moon against the precession merely runs out of room. Both
     used to be reported as a best small-integer ratio with a residual. */
  let best=null, stopped='budget';
  if(isFinite(A)&&isFinite(B)&&A>0&&B>0){
    const cf=oscContFrac(A/B,maxA);
    stopped=cf.stopped;
    for(const c of cf.convergents){
      /* BOTH counts are bounded, not just the denominator. oscContFrac caps q
         because a Lagrange number only needs the denominator bounded; a
         commensurability needs both, since "how many of A equal how many of B"
         is nonsense if either count runs past what anyone would call small.
         Dropping this cost the symmetry: year against moon came back 334:4131
         where moon against year gave 235:19, and the two are the same question
         asked in the other order. */
      if(!(c.q>=1&&c.p>=1&&c.q<=maxA&&c.p<=maxA)) continue;
      const errorDays=Math.abs(c.q*A-c.p*B);
      if(!best||errorDays<best.errorDays)
        best={nA:c.q,nB:c.p,errorDays,spanDays:(c.q*A+c.p*B)/2};
    }
  }
  if(!best) best={nA:1,nB:1,errorDays:Math.abs(A-B),spanDays:(A+B)/2};
  best.ppm=best.errorDays/best.spanDays*1e6;
  best.stopped=stopped;
  /* EXACT is not the same as TIGHT, and only the engine knows which this is */
  best.exact=(stopped==='terminated');
  const ratio=Math.max(A,B)/Math.min(A,B);
  best.reachable=ratio<=maxA;
  best.maxTerm=maxA;              /* the bound the caller may quote beside a capped answer */
  best.meaningful=best.reachable&&best.ppm<1e5;
  /* ── A TAUTOLOGY IS NOT A RESULT, AND ONLY THE ENGINE CAN SAY SO ONCE ──────
     Some periods in this atlas are DEFINED as integer multiples of another:
     the Saros is 223 synodic months and the Inex is 358 of them, declared on
     the cycle entry as constructedFrom. Their ratio against the synodic month
     terminates at exactly that integer -- the definition read back, carrying no
     information about the sky at all.
     The resonance web learned to draw those differently and computed the test
     itself, which immediately made two answers to one question: the web said
     "by construction" while the linked view, reading the same pair through this
     same function, still said "exact by definition". That is the split this
     engine was merged to end. The test belongs here, once, and every surface
     inherits it. `informative` is the field a caller should gate a claim on:
     meaningful says the question had an answer, informative says the answer was
     not simply the input. */
  const _ctA=a&&a.constructedFrom, _ctB=b&&b.constructedFrom;
  best.tautology=!!((_ctA&&_ctA.key&&b&&_ctA.key===b.key)||(_ctB&&_ctB.key&&a&&_ctB.key===a.key));
  best.constructedTimes=best.tautology?((_ctA&&_ctA.key===(b&&b.key))?_ctA.times:_ctB.times):null;
  best.informative=best.meaningful&&!best.tautology;
  best.refusal=best.meaningful?null:(best.reachable
    ? `the closest ratio within ${maxA} still misses by ${(best.ppm/1e4).toFixed(1)}% — these periods do not lock`
    : `the periods differ by a factor of ${ratio.toExponential(2)}, beyond the ${maxA} this search considers: small-integer commensurability is not a meaningful question for this pair, and no number is reported rather than a number that means nothing`);
  return best;
}

