function gwMergerTime(a0,e0,M,c5){          // numeric — the honest general-e answer
  let a=a0,e=e0,t=0;
  for(let i=0;i<20000&&a>12/Math.pow(c5,0.4);i++){
    const [da,de]=gwPetersRates(a,e,M,c5);
    const h=Math.min(0.5,-0.004*a/da); a+=da*h; e=Math.max(0,e+de*h); t+=h;
    if(a<=0.09) break;
  }
  return t;
}

function gravAccel(B,ax,ay){
  const n=B.length; for(let i=0;i<n;i++){ ax[i]=0; ay[i]=0; }
  for(let i=0;i<n;i++)for(let j=i+1;j<n;j++){
    const dx=B[j].x-B[i].x, dy=B[j].y-B[i].y, r2=dx*dx+dy*dy, inv=1/(r2*Math.sqrt(r2));
    ax[i]+=B[j].m*dx*inv; ay[i]+=B[j].m*dy*inv;
    ax[j]-=B[i].m*dx*inv; ay[j]-=B[i].m*dy*inv; }
}

const _gAx=[0,0,0],_gAy=[0,0,0];

function gravStep(B,h){
  for(let s=0;s<4;s++){
    for(const b of B){ b.x+=GRAV_CS[s]*b.vx*h; b.y+=GRAV_CS[s]*b.vy*h; }
    if(GRAV_DS[s]){ gravAccel(B,_gAx,_gAy);
      for(let i=0;i<B.length;i++){ B[i].vx+=GRAV_DS[s]*_gAx[i]*h; B[i].vy+=GRAV_DS[s]*_gAy[i]*h; } } }
}

function gravRmin(B){ let r=1e9;
  for(let i=0;i<B.length;i++)for(let j=i+1;j<B.length;j++)
    r=Math.min(r,Math.hypot(B[j].x-B[i].x,B[j].y-B[i].y)); return r; }

function gravInvariants(B){
  let E=0,Lz=0,Px=0,Py=0;
  for(const b of B){ E+=.5*b.m*(b.vx*b.vx+b.vy*b.vy); Lz+=b.m*(b.x*b.vy-b.y*b.vx); Px+=b.m*b.vx; Py+=b.m*b.vy; }
  for(let i=0;i<B.length;i++)for(let j=i+1;j<B.length;j++)
    E-=B[i].m*B[j].m/Math.hypot(B[j].x-B[i].x,B[j].y-B[i].y);
  return {E,Lz,P:Math.hypot(Px,Py)};
}

const QM_N=512, QM_L=80, QM_DX=QM_L/QM_N;

const qmX=i=>-QM_L/2+i*QM_DX, qmK=i=>(i<QM_N/2?i:i-QM_N)*2*Math.PI/QM_L;

function qmFFT(re,im,inv){
  const n=re.length;
  for(let i=1,j=0;i<n;i++){ let bit=n>>1;
    for(;j&bit;bit>>=1) j^=bit; j^=bit;
    if(i<j){ const tr=re[i];re[i]=re[j];re[j]=tr; const ti=im[i];im[i]=im[j];im[j]=ti; } }
  for(let len=2;len<=n;len<<=1){
    const ang=(inv?2:-2)*Math.PI/len, wr=Math.cos(ang), wi=Math.sin(ang);
    for(let i=0;i<n;i+=len){
      let cr=1, ci=0;
      for(let k=0;k<len/2;k++){
        const ur=re[i+k], ui=im[i+k];
        const vr=re[i+k+len/2]*cr-im[i+k+len/2]*ci, vi=re[i+k+len/2]*ci+im[i+k+len/2]*cr;
        re[i+k]=ur+vr; im[i+k]=ui+vi; re[i+k+len/2]=ur-vr; im[i+k+len/2]=ui-vi;
        const ncr=cr*wr-ci*wi; ci=cr*wi+ci*wr; cr=ncr; } } }
  if(inv) for(let i=0;i<n;i++){ re[i]/=n; im[i]/=n; }
}

function qmPropagate(re,im,V,n,dt){
  for(let s=0;s<n;s++){
    for(let i=0;i<QM_N;i++){ const ph=-V[i]*dt/2, c=Math.cos(ph), si=Math.sin(ph);
      const r=re[i]*c-im[i]*si; im[i]=re[i]*si+im[i]*c; re[i]=r; }
    qmFFT(re,im,false);
    for(let i=0;i<QM_N;i++){ const k=qmK(i), ph=-k*k/2*dt, c=Math.cos(ph), si=Math.sin(ph);
      const r=re[i]*c-im[i]*si; im[i]=re[i]*si+im[i]*c; re[i]=r; }
    qmFFT(re,im,true);
    for(let i=0;i<QM_N;i++){ const ph=-V[i]*dt/2, c=Math.cos(ph), si=Math.sin(ph);
      const r=re[i]*c-im[i]*si; im[i]=re[i]*si+im[i]*c; re[i]=r; }
  }
  return [re,im];
}

function qmGaussian(x0,k0,sig){
  const re=new Float64Array(QM_N), im=new Float64Array(QM_N); let nrm=0;
  for(let i=0;i<QM_N;i++){ const g=Math.exp(-((qmX(i)-x0)**2)/(4*sig*sig));
    re[i]=g*Math.cos(k0*qmX(i)); im[i]=g*Math.sin(k0*qmX(i)); nrm+=g*g*QM_DX; }
  const f=1/Math.sqrt(nrm); for(let i=0;i<QM_N;i++){ re[i]*=f; im[i]*=f; }
  return [re,im];
}

function qmHarmonic(om){ const V=new Float64Array(QM_N);
  for(let i=0;i<QM_N;i++) V[i]=0.5*om*om*qmX(i)*qmX(i); return V; }

function qmMoments(re,im){
  let n=0,x=0,x2=0;
  for(let i=0;i<QM_N;i++){ const d=(re[i]*re[i]+im[i]*im[i])*QM_DX, q=qmX(i); n+=d; x+=q*d; x2+=q*q*d; }
  const mx=x/(n||1e-300);
  return {norm:n, x:mx, sigma:Math.sqrt(Math.max(0,x2/(n||1e-300)-mx*mx))};
}

const QCD_HC=0.1973, QCD_AS=0.3, QCD_SIG=0.9, QCD_BRK=1.10, QCD_FM=2.6;

const qcdV=r=>-(4/3)*QCD_AS*QCD_HC/r+QCD_SIG*r;

const qcdAlphaS=Q=>{ const nf=Q<1.27?3:Q<4.18?4:5, L=0.21;                 // 1-loop, threshold-crude (declared)
  return 12*Math.PI/((33-2*nf)*Math.log((Q*Q)/(L*L))); };

function topoHopfPts(th,ph,N,R){
  N=N||160; R=R||1.9; const pts=[];
  for(let k=0;k<N;k++){ const t=k/N*2*Math.PI, z1r=Math.cos(th/2)*Math.cos(t+ph), z1i=Math.cos(th/2)*Math.sin(t+ph), z2r=Math.sin(th/2)*Math.cos(t), z2i=Math.sin(th/2)*Math.sin(t), w=1-z2i;
    pts.push([z1r/w*R, z2r/w*R, z1i/w*R]); }
  return pts;
}

function topoLinkPure(A,B){
  let s=0;
  for(let i=0;i<A.length;i++){
    const a=A[i], a2=A[(i+1)%A.length];
    const vax=a2[0]-a[0], vay=a2[1]-a[1], vaz=a2[2]-a[2];
    const amx=(a[0]+a2[0])/2, amy=(a[1]+a2[1])/2, amz=(a[2]+a2[2])/2;
    for(let j=0;j<B.length;j++){
      const b=B[j], b2=B[(j+1)%B.length];
      const vbx=b2[0]-b[0], vby=b2[1]-b[1], vbz=b2[2]-b[2];
      const rx=amx-(b[0]+b2[0])/2, ry=amy-(b[1]+b2[1])/2, rz=amz-(b[2]+b2[2])/2;
      const rl=Math.hypot(rx,ry,rz);
      const cx=vay*vbz-vaz*vby, cy=vaz*vbx-vax*vbz, cz=vax*vby-vay*vbx;
      s+=(cx*rx+cy*ry+cz*rz)/(rl*rl*rl);
    }
  }
  return s/(4*Math.PI);
}

function topoHopfPair(th1,th2,ph1,ph2,N){
  N=N||240;
  return [topoHopfPts(th1,ph1,N,1.9), topoHopfPts(th2,ph2,N,1.9)];
}

