function chaosRK4(sys,p,s,h){ const f=sys.f;
  const k1=f(p,s[0],s[1],s[2]);
  const k2=f(p,s[0]+h/2*k1[0],s[1]+h/2*k1[1],s[2]+h/2*k1[2]);
  const k3=f(p,s[0]+h/2*k2[0],s[1]+h/2*k2[1],s[2]+h/2*k2[2]);
  const k4=f(p,s[0]+h*k3[0],s[1]+h*k3[1],s[2]+h*k3[2]);
  return [s[0]+h/6*(k1[0]+2*k2[0]+2*k3[0]+k4[0]),
          s[1]+h/6*(k1[1]+2*k2[1]+2*k3[1]+k4[1]),
          s[2]+h/6*(k1[2]+2*k2[2]+2*k3[2]+k4[2])]; }

function mathErfc(x){ let f=0; for(let n=80;n>=1;n--) f=(n/2)/(x+f);
  return Math.exp(-x*x)/Math.sqrt(Math.PI)/(x+f); }

function mathErf(x){ const a=Math.abs(x), sg=x<0?-1:1;
  if(a<2){ let sum=a, term=a; const x2=a*a;
    for(let n=1;n<300;n++){ term*=-x2/n; const add=term/(2*n+1); sum+=add;
      if(Math.abs(add)<1e-18*Math.abs(sum)) break; }
    return sg*2/Math.sqrt(Math.PI)*sum; }
  return sg*(1-mathErfc(a)); }

function kinRandDir(rnd){                       // uniform on the sphere, from the SEEDED stream
  const u=2*rnd()-1, ph=2*Math.PI*rnd(), r=Math.sqrt(Math.max(0,1-u*u));
  return [r*Math.cos(ph), u, r*Math.sin(ph)];
}

function kinInitPure(N,L,seed,confined,mono,spread){
  const rnd=mulberry(seed), P=new Float64Array(N*3), V=new Float64Array(N*3);
  const half=confined?L*0.24:L*0.5;
  for(let i=0;i<N;i++){
    P[i*3]=confined?(-L*0.5+rnd()*half):(rnd()*L-L*0.5);
    P[i*3+1]=rnd()*L-L*0.5; P[i*3+2]=rnd()*L-L*0.5;
    const sp=(mono?1:(0.4+rnd()*1.2))*spread, d=kinRandDir(rnd);
    V[i*3]=d[0]*sp; V[i*3+1]=d[1]*sp; V[i*3+2]=d[2]*sp;
  }
  return {pos:P,vel:V};
}

function kinStepPure(P,V,L,R,h,n){              // advances IN PLACE; returns the wall impulse delivered
  const N=P.length/3, lim=L*0.5-R, dd=4*R*R; let impulse=0;
  for(let s=0;s<n;s++){
    for(let i=0;i<N;i++)for(let d=0;d<3;d++){ const k=i*3+d; P[k]+=V[k]*h;
      if(P[k]>lim){ P[k]=lim; impulse+=2*Math.abs(V[k]); V[k]=-Math.abs(V[k]); }
      else if(P[k]<-lim){ P[k]=-lim; impulse+=2*Math.abs(V[k]); V[k]=Math.abs(V[k]); } }
    for(let i=0;i<N;i++)for(let j=i+1;j<N;j++){
      const dx=P[j*3]-P[i*3], dy=P[j*3+1]-P[i*3+1], dz=P[j*3+2]-P[i*3+2], d2=dx*dx+dy*dy+dz*dz;
      if(d2<dd&&d2>1e-9){ const dist=Math.sqrt(d2), nx=dx/dist, ny=dy/dist, nz=dz/dist;
        const vn=(V[i*3]-V[j*3])*nx+(V[i*3+1]-V[j*3+1])*ny+(V[i*3+2]-V[j*3+2])*nz;
        if(vn>0){ V[i*3]-=vn*nx; V[i*3+1]-=vn*ny; V[i*3+2]-=vn*nz;
          V[j*3]+=vn*nx; V[j*3+1]+=vn*ny; V[j*3+2]+=vn*nz;
          const ov=(2*R-dist)*0.5; P[i*3]-=nx*ov; P[i*3+1]-=ny*ov; P[i*3+2]-=nz*ov;
          P[j*3]+=nx*ov; P[j*3+1]+=ny*ov; P[j*3+2]+=nz*ov; } }
    }
  }
  return impulse;
}

function kinMoments(V){                         // unit mass throughout: kT ≡ ⟨v²⟩/3 by equipartition
  const N=V.length/3; let ke=0, px=0, py=0, pz=0;
  for(let i=0;i<N;i++){ ke+=V[i*3]*V[i*3]+V[i*3+1]*V[i*3+1]+V[i*3+2]*V[i*3+2];
    px+=V[i*3]; py+=V[i*3+1]; pz+=V[i*3+2]; }
  const meanV2=ke/N, kT=meanV2/3;
  return {ke,kT,meanV2,vrms:Math.sqrt(meanV2),vmp:Math.sqrt(2*kT),vmean:Math.sqrt(8*kT/Math.PI),px,py,pz};
}

const kinMBPdf=(v,kT)=>4*Math.PI*Math.pow(1/(2*Math.PI*kT),1.5)*v*v*Math.exp(-v*v/(2*kT));

const kinMaxwellCdf=(v,kT)=>{ const sg=Math.sqrt(kT);
  return mathErf(v/(sg*Math.SQRT2))-Math.sqrt(2/Math.PI)*(v/sg)*Math.exp(-v*v/(2*kT)); };

function kinSampleMeanSpeed(V){ const n=V.length/3; let acc=0;
  for(let i=0;i<n;i++) acc+=Math.hypot(V[i*3],V[i*3+1],V[i*3+2]); return acc/n; }

function kinKS(V,kT){                         // Kolmogorov–Smirnov distance to the Maxwell speed law
  const n=V.length/3, sp=[];
  for(let i=0;i<n;i++) sp.push(Math.hypot(V[i*3],V[i*3+1],V[i*3+2]));
  sp.sort((x,y)=>x-y); let D=0;
  for(let i=0;i<n;i++){ const Fc=kinMaxwellCdf(sp[i],kT);
    D=Math.max(D,Math.abs((i+1)/n-Fc),Math.abs(Fc-i/n)); }
  return {D, critical95:1.35810/Math.sqrt(n), n}; }

function kinEntropyPure(P,L,gx,gy,gz){          // coarse-grained occupancy entropy S = −Σ p ln p
  const N=P.length/3, cell=new Float64Array(gx*gy*gz);
  const at=(v,g)=>Math.min(g-1,Math.max(0,Math.floor((v/L+0.5)*g)));
  for(let i=0;i<N;i++) cell[(at(P[i*3],gx)*gy+at(P[i*3+1],gy))*gz+at(P[i*3+2],gz)]++;
  let S=0; for(let c=0;c<cell.length;c++) if(cell[c]>0){ const p=cell[c]/N; S-=p*Math.log(p); }
  return {S,Smax:Math.log(gx*gy*gz)};
}

const kinWallSide=(L,R)=>L-2*R;

const kinPressure=(impulse,t,L,R)=>impulse/Math.max(t,1e-12)/(6*kinWallSide(L,R)**2);

const kinPacking=(N,R,L)=>N*(4/3)*Math.PI*R*R*R/kinWallSide(L,R)**3;

const kinZ=(P,L,R,N,kT)=>P*kinWallSide(L,R)**3/(N*kT);

const kinZCarnahanStarling=eta=>(1+eta+eta*eta-eta*eta*eta)/Math.pow(1-eta,3);

function shPlm(l,m,x){   // associated Legendre P_l^m, m≥0 (Condon–Shortley)
  let pmm=1; if(m>0){ const s=Math.sqrt(Math.max(0,1-x*x)); let f=1; for(let i=1;i<=m;i++){ pmm*=-f*s; f+=2; } }
  if(l===m) return pmm;
  let pmm1=x*(2*m+1)*pmm; if(l===m+1) return pmm1;
  let pll=0;
  for(let ll=m+2;ll<=l;ll++){ pll=((2*ll-1)*x*pmm1-(ll+m-1)*pmm)/(ll-m); pmm=pmm1; pmm1=pll; }
  return pll;
}

const _shFact=(n=>{ const a=[1]; for(let i=1;i<=40;i++) a[i]=a[i-1]*i; return a; })();

function shNlm(l,m){ return Math.sqrt((2*l+1)/(4*Math.PI)*_shFact[l-m]/_shFact[l+m]); }

function shY(l,m,th,ph){ const am=Math.abs(m), N=shNlm(l,am)*shPlm(l,am,Math.cos(th));
  if(m>0) return Math.SQRT2*N*Math.cos(m*ph);
  if(m<0) return Math.SQRT2*N*Math.sin(am*ph);
  return N; }

const KDV_N=256, KDV_L=60, KDV_NX=96, KDV_HW=84;

const kdvSech=x=>1/Math.cosh(x);

const kdvSoliton=(c,x,x0)=>0.5*c*kdvSech(0.5*Math.sqrt(c)*(x-x0))**2;

const _kdvK=(()=>{ const k=new Float64Array(KDV_N); for(let i=0;i<KDV_N;i++) k[i]=(i<KDV_N/2?i:i-KDV_N)*2*Math.PI/KDV_L; return k; })();

function kdvNonlin(hr,hi){   // N(û) = −3ik·FFT(u²), computed in the real frame
  const ur=Float64Array.from(hr), ui=Float64Array.from(hi); qmFFT(ur,ui,true);
  for(let i=0;i<KDV_N;i++){ ur[i]=ur[i]*ur[i]; ui[i]=0; }   // u² (real)
  qmFFT(ur,ui,false);
  const nr=new Float64Array(KDV_N), ni=new Float64Array(KDV_N);
  for(let i=0;i<KDV_N;i++){ nr[i]=3*_kdvK[i]*ui[i]; ni[i]=-3*_kdvK[i]*ur[i]; }
  return [nr,ni];
}

function kdvEvolve(u,dt,nsteps){   // integrating-factor RK4, rebased each call (t=0) → no large-t precision loss
  let vr=Float64Array.from(u), vi=new Float64Array(KDV_N); qmFFT(vr,vi,false);
  const applyE=(r,im,tt,sg)=>{ const or=new Float64Array(KDV_N),oi=new Float64Array(KDV_N);
    for(let i=0;i<KDV_N;i++){ const ang=sg*_kdvK[i]**3*tt, c=Math.cos(ang),s=Math.sin(ang);
      or[i]=r[i]*c-im[i]*s; oi[i]=r[i]*s+im[i]*c; } return [or,oi]; };
  const F=(r,im,tt)=>{ const [hr,hi]=applyE(r,im,tt,1); const [nr,ni]=kdvNonlin(hr,hi); return applyE(nr,ni,tt,-1); };
  let t=0;
  for(let s=0;s<nsteps;s++){
    const [k1r,k1i]=F(vr,vi,t);
    const [k2r,k2i]=F(vr.map((v,i)=>v+dt/2*k1r[i]),vi.map((v,i)=>v+dt/2*k1i[i]),t+dt/2);
    const [k3r,k3i]=F(vr.map((v,i)=>v+dt/2*k2r[i]),vi.map((v,i)=>v+dt/2*k2i[i]),t+dt/2);
    const [k4r,k4i]=F(vr.map((v,i)=>v+dt*k3r[i]),vi.map((v,i)=>v+dt*k3i[i]),t+dt);
    for(let i=0;i<KDV_N;i++){ vr[i]+=dt/6*(k1r[i]+2*k2r[i]+2*k3r[i]+k4r[i]); vi[i]+=dt/6*(k1i[i]+2*k2i[i]+2*k3i[i]+k4i[i]); }
    t+=dt;
  }
  const [fr,fi]=applyE(vr,vi,t,1); qmFFT(fr,fi,true);
  return fr;
}

function kdvGridX(i){ return i*(KDV_L/KDV_N)-KDV_L/2; }

function kdvTwoSoliton(c1,c2,x1,x2){
  const u=new Float64Array(KDV_N);
  for(let i=0;i<KDV_N;i++) u[i]=kdvSoliton(c1,kdvGridX(i),x1)+kdvSoliton(c2,kdvGridX(i),x2);
  return u;
}

function kdvInvariants(u){ const dx=KDV_L/KDV_N; let I1=0,I2=0,I3=0;
  for(let i=0;i<KDV_N;i++){ const ux=(u[(i+1)%KDV_N]-u[(i-1+KDV_N)%KDV_N])/(2*dx);
    I1+=u[i]*dx; I2+=u[i]*u[i]*dx; I3+=(u[i]**3-0.5*ux*ux)*dx; }
  return {I1,I2,I3}; }

const retOmegaSym=(k,m)=>Math.sqrt(k/m);

const retOmegaAnti=(k,kap,m)=>Math.sqrt((k+2*kap)/m);

const retBeatTime=(k,kap,m)=>Math.PI/(retOmegaAnti(k,kap,m)-retOmegaSym(k,m));

function retEnergyPure(x1,x2,v1,v2,k,kap,m){
  const E1=0.5*m*v1*v1+0.5*k*x1*x1, E2=0.5*m*v2*v2+0.5*k*x2*x2, Ec=0.5*kap*(x1-x2)**2;
  return {E1,E2,Ec,Et:E1+E2+Ec}; }

function retAccel(x1,x2,k,kap,m){ return [(-k*x1-kap*(x1-x2))/m, (-k*x2-kap*(x2-x1))/m]; }

function retLeapfrog(st,k,kap,m,h,n){                          // velocity Verlet on [x1,x2,v1,v2]
  let x1=st[0], x2=st[1], v1=st[2], v2=st[3];
  for(let i=0;i<n;i++){ const a=retAccel(x1,x2,k,kap,m);
    v1+=a[0]*h/2; v2+=a[1]*h/2; x1+=v1*h; x2+=v2*h;
    const b=retAccel(x1,x2,k,kap,m); v1+=b[0]*h/2; v2+=b[1]*h/2; }
  return [x1,x2,v1,v2]; }

function retAnalytic(t,k,kap,m){                               // exact solution for x1(0)=1, everything else zero
  const ws=retOmegaSym(k,m), wa=retOmegaAnti(k,kap,m);
  const cs=Math.cos(ws*t), ca=Math.cos(wa*t), ss=Math.sin(ws*t), sa=Math.sin(wa*t);
  return [(cs+ca)/2, (cs-ca)/2, (-ws*ss-wa*sa)/2, (-ws*ss+wa*sa)/2]; }

const retDrivenAmp=(w,w0,g,F)=>F/Math.sqrt((w0*w0-w*w)**2+(g*w)**2);

const retPeakOmega=(w0,g)=>Math.sqrt(Math.max(0,w0*w0-g*g/2));

const retPeakAmp=(w0,g,F)=>F/(g*Math.sqrt(Math.max(1e-300,w0*w0-g*g/4)));

const retWirelessU=(k,Q)=>k*Q;

const retWirelessEta=(k,Q)=>{ const U=k*Q; return U*U/(1+Math.sqrt(1+U*U))**2; };

const retWirelessEtaAlt=(k,Q)=>{ const s=Math.sqrt(1+(k*Q)**2); return (s-1)/(s+1); };

const dipPattern=th=>Math.sin(th)**2;

const dipPatternNorm=th=>3/(8*Math.PI)*Math.sin(th)**2;

function dipPatternIntegral(N){                                // midpoint quadrature of ∫sin²θ dΩ
  let acc=0; for(let i=0;i<N;i++){ const th=(i+0.5)/N*Math.PI; acc+=Math.sin(th)**2*Math.sin(th); }
  return 2*Math.PI*acc*(Math.PI/N); }

const DIP_PATTERN_EXACT=8*Math.PI/3;

const dipLarmorRel=w=>w**4;

const dipRayleighRatio=(lamShort,lamLong)=>(lamLong/lamShort)**4;

const dipWavefrontSpacing=(w,c)=>Math.PI*c/w;

const dipHalfPower=()=>Math.PI/4;

function emHopfPtPure(q0,axis,t,S){
  const c=Math.cos(t), sn=Math.sin(t);
  const e = axis==='i'?[c,sn,0,0]:[c,0,sn,0];                     // e^{t·i} or e^{t·j}
  const w=q0[0]*e[0]-q0[1]*e[1]-q0[2]*e[2]-q0[3]*e[3];            // Hamilton product q0·e
  const x=q0[0]*e[1]+q0[1]*e[0]+q0[2]*e[3]-q0[3]*e[2];
  const y=q0[0]*e[2]-q0[1]*e[3]+q0[2]*e[0]+q0[3]*e[1];
  const z=q0[0]*e[3]+q0[1]*e[2]-q0[2]*e[1]+q0[3]*e[0];
  const d=1-z+1e-9;                                               // stereographic S³→R³ from (0,0,0,1)
  return [w/d*S, x/d*S, y/d*S];
}

function emFibreTangentPure(q0,axis,t,S,h){
  const a=emHopfPtPure(q0,axis,t-h,S), b=emHopfPtPure(q0,axis,t+h,S);
  return [(b[0]-a[0])/(2*h),(b[1]-a[1])/(2*h),(b[2]-a[2])/(2*h)];
}

const emRightI=q=>[-q[1],q[0],q[3],-q[2]];

const emRightJ=q=>[-q[2],-q[3],q[0],q[1]];

function emProjTangent(q,v){ const d=1-q[3];                      // d(stereographic)/dq applied to v
  return [(v[0]+q[0]*v[3]/d)/d,(v[1]+q[1]*v[3]/d)/d,(v[2]+q[2]*v[3]/d)/d]; }

function emNullResidual(q){                                       // E·B and |E|/|B| at ONE point of S³
  const E=emProjTangent(q,emRightI(q)), B=emProjTangent(q,emRightJ(q));
  const nE=Math.hypot(E[0],E[1],E[2]), nB=Math.hypot(B[0],B[1],B[2]);
  return {E,B,cosine:(E[0]*B[0]+E[1]*B[1]+E[2]*B[2])/(nE*nB), ratio:nE/nB, magnitude:nE};
}

function emFibreLoop(q0,axis,S,N){                                // closed polyline of one fibre
  const out=[]; for(let i=0;i<N;i++) out.push(emHopfPtPure(q0,axis,i/N*2*Math.PI,S));
  return out;
}

function emBaseQ(theta,phi){ const ch=Math.cos(theta/2), sh=Math.sin(theta/2); return [ch*Math.cos(phi),ch*Math.sin(phi),sh,0]; }

function cpFieldPure(st,B0,E0,x){
  if(st==='exb') return [[E0,0,0],[0,0,B0]];
  if(st==='gradB'){ const b=B0*(1+0.25*x[0]); return [[0,0,0],[0,0,b]]; }   // B increases with x → grad-B drift
  if(st==='mirror'){ const z=x[2], bz=B0*(1+0.5*z*z);
    /* B_r = -(r/2) dB_z/dz = -0.5 B0 z r, and the r MATTERS. It used to be -0.5 B0 z with
       no r at all, which made the radial field independent of the distance from the axis and
       left div B = B0 z (1 - 0.5/r) instead of 0. A bottle that is not divergence free is
       not a magnetic field, and the magnetic moment — the adiabatic invariant this station
       exists to show — drifted by 60% even at a gyroradius of a hundredth of the field
       scale. With the r restored, div B is exactly zero and mu is conserved. */
    return [[0,0,0],[-0.5*B0*z*x[0], -0.5*B0*z*x[1], bz]]; }
  return [[0,0,0],[0,0,B0]];   // cyclotron: pure uniform B
}

function cpBorisPure(st,B0,E0,qm,x,v,dt){ const [E,B]=cpFieldPure(st,B0,E0,x);
  const t=[qm*B[0]*dt/2,qm*B[1]*dt/2,qm*B[2]*dt/2], t2=t[0]*t[0]+t[1]*t[1]+t[2]*t[2], s=t.map(a=>2*a/(1+t2));
  const vm=[v[0]+qm*E[0]*dt/2,v[1]+qm*E[1]*dt/2,v[2]+qm*E[2]*dt/2];
  const vpr=[vm[0]+(vm[1]*t[2]-vm[2]*t[1]),vm[1]+(vm[2]*t[0]-vm[0]*t[2]),vm[2]+(vm[0]*t[1]-vm[1]*t[0])];
  const vp=[vm[0]+(vpr[1]*s[2]-vpr[2]*s[1]),vm[1]+(vpr[2]*s[0]-vpr[0]*s[2]),vm[2]+(vpr[0]*s[1]-vpr[1]*s[0])];
  const vn=[vp[0]+qm*E[0]*dt/2,vp[1]+qm*E[1]*dt/2,vp[2]+qm*E[2]*dt/2];
  return [[x[0]+vn[0]*dt,x[1]+vn[1]*dt,x[2]+vn[2]*dt],vn];
}

function rdTuring(F,k,Du,Dv){
  const A=F+k, disc=F*F-4*F*A*A, out={F,k,Du,Dv,A,disc,exists:disc>=0,branches:[]};
  // the trivial state is exact and always stable — state it as a theorem, at every q
  out.trivial={eig1:q=>-F-Du*q*q, eig2:q=>-(F+k)-Dv*q*q, alwaysStable:true};
  if(!out.exists) return out;
  const sq=Math.sqrt(disc);
  for(const v of [(F+sq)/(2*A),(F-sq)/(2*A)]){
    if(!(v>1e-12)) continue;
    const u=A/v, fu=-v*v-F, fv=-2*A, gu=v*v, gv=A;
    const tr=fu+gv, det0=fu*gv-fv*gu, B=Dv*fu+Du*gv, d=B*B-4*Du*Dv*det0;
    const homStable=tr<0&&det0>0, turing=homStable&&B>0&&d>0;
    const br={u,v,tr,det0,B,homStable,turing,qc:NaN,lam:NaN,band:null,qMax:NaN,lamMax:NaN,rate:NaN};
    if(turing){ br.qc=Math.sqrt(B/(2*Du*Dv)); br.lam=2*Math.PI/br.qc;
      const s2=Math.sqrt(d); br.band=[Math.sqrt(Math.max(0,(B-s2)/(2*Du*Dv))),Math.sqrt((B+s2)/(2*Du*Dv))];
      // the mode that actually grows fastest (q_c only coincides with it AT threshold)
      let best=-Infinity,qb=0; const lo=br.band[0]*0.5, hi=br.band[1]*1.5;
      for(let i=1;i<=1200;i++){ const q=lo+(hi-lo)*i/1200;
        const trq=tr-(Du+Dv)*q*q, detq=Du*Dv*q**4-B*q*q+det0, dd=trq*trq-4*detq;
        const g=dd>=0?(trq+Math.sqrt(dd))/2:trq/2; if(g>best){best=g;qb=q;} }
      br.qMax=qb; br.lamMax=2*Math.PI/qb; br.rate=best; }
    out.branches.push(br); }
  out.active=out.branches.find(b=>b.turing)||out.branches.find(b=>b.homStable)||out.branches[0];
  return out;
}

function heCyclePure(Th,Tc,g,V1,V2){
  const nR=1;
  const V3=V2*Math.pow(Th/Tc,1/(g-1)), V4=V1*Math.pow(Th/Tc,1/(g-1));
  const P=(V,T)=>nR*T/V;
  const pts=[]; const seg=(Va,Vb,Tf)=>{ const M=40; for(let m=0;m<=M;m++){ const V=Va+(Vb-Va)*m/M; pts.push([V,P(V,Tf(V))]); } };
  seg(V1,V2,()=>Th);
  seg(V2,V3,V=>Th*Math.pow(V2/V,g-1));
  seg(V3,V4,()=>Tc);
  seg(V4,V1,V=>Tc*Math.pow(V4/V,g-1));
  /* the two isothermal heats, in closed form: Q = nRT ln(V_b/V_a) */
  const Qin=nR*Th*Math.log(V2/V1), Qout=nR*Tc*Math.log(V3/V4);
  return {pts,Th,Tc,nR,V1,V2,V3,V4,Qin,Qout,work:Qin-Qout,gamma:g};
}

const BB_H=6.62607015e-34, BB_C=2.99792458e8, BB_KB=1.380649e-23, BB_SIG=5.670374419e-8, BB_C2=1.438776877e-2;

function bbPlanck(lam,T){ return (2*BB_H*BB_C*BB_C/Math.pow(lam,5))/(Math.exp(BB_C2/(lam*T))-1); }

const NUC_aV=15.75, NUC_aS=17.8, NUC_aC=0.711, NUC_aA=23.7, NUC_aP=11.18;

function nucBE(A,Z){ const N=A-Z; let d=0; if(A%2===0) d=(Z%2===0)?NUC_aP/Math.sqrt(A):-NUC_aP/Math.sqrt(A);
  return NUC_aV*A - NUC_aS*Math.pow(A,2/3) - NUC_aC*Z*(Z-1)/Math.pow(A,1/3) - NUC_aA*(A-2*Z)*(A-2*Z)/A + d; }

function nucBperA(A,Z){ return nucBE(A,Z)/A; }

function nucBestZ(A){ let bz=1,bb=-1e9; for(let Z=1;Z<A;Z++){ const b=nucBperA(A,Z); if(b>bb){bb=b;bz=Z;} } return bz; }

const LENS_RS=1, LENS_BCRIT=3*Math.sqrt(3)/2;

function lensPeriU(b){   // smallest positive root of the null first integral f(u)=1/b²−u²+R_s u³ (periapsis)
  const B=Math.abs(b), f=u=>1/(B*B)-u*u+LENS_RS*u*u*u; let prev=f(1e-6);
  for(let u=1e-4;u<=1/LENS_RS;u+=1e-4){ const cur=f(u); if(prev>0&&cur<=0){ let a=u-1e-4,bb=u;
    for(let k=0;k<50;k++){ const m=(a+bb)/2; (f(m)>0?a=m:bb=m); } return (a+bb)/2; } prev=cur; }
  return -1;
}

function lensAlpha(b){   // EXACT deflection via quadrature α = 2∫₀^{u_max} du/√f − π ; null if captured
  const B=Math.abs(b); if(B<LENS_BCRIT) return null; const um=lensPeriU(B); if(um<0) return null;
  /* one line, not two: the extractor's statement walker stops at a newline inside a
     `const a = …,` list when the next line starts with an identifier, and du and f were
     invisible to the closure because of the wrap */
  let s=0; const N=6000; for(let i=0;i<N;i++){ const t=(i+0.5)/N*(Math.PI/2), u=um*Math.sin(t), du=um*Math.cos(t)*(Math.PI/2)/N, f=1/(B*B)-u*u+LENS_RS*u*u*u; if(f>0) s+=du/Math.sqrt(f); }
  return 2*s-Math.PI;
}

const teMroot=ZT=>Math.sqrt(1+ZT);

function teEta(ZT,tau){ const M=teMroot(ZT); return (1-tau)*(M-1)/(M+tau); }

function teCOP(ZT,tau){ const M=teMroot(ZT); return tau/(1-tau)*(M-1/tau)/(M+1); }

const GW_G=6.674e-11, GW_C=2.998e8, GW_MSUN=1.989e30;

function gwChirpMass(m1,m2){ return Math.pow(m1*m2,3/5)/Math.pow(m1+m2,1/5); }

