const he3GapA=(th,D0)=>D0*Math.abs(Math.sin(th));

const he3GapB=(th,D0)=>D0;

const he3Gap=(phase,th,D0)=>phase==='A'?he3GapA(th,D0):he3GapB(th,D0);

