const nuJarlskogAngles=(t12,t13,t23,d)=>Math.cos(t12)*Math.sin(t12)*Math.cos(t23)*Math.sin(t23)*Math.pow(Math.cos(t13),2)*Math.sin(t13)*Math.sin(d);

