function cosmoSimpson(f,a,b,n){ n=2*Math.ceil(n/2); const h=(b-a)/n; let s=f(a)+f(b);
  for(let i=1;i<n;i++) s+=(i%2?4:2)*f(a+i*h); return s*h/3; }

const cosmoE=(z,Om,Or,OL)=>Math.sqrt(Om*Math.pow(1+z,3)+Or*Math.pow(1+z,4)+OL);

const COSMO_OM_LO=0.10;

const COSMO_OM_HI=1.00;

const COSMO_OM_N=7;

const cosmoOmAt=k=>COSMO_OM_LO+(COSMO_OM_HI-COSMO_OM_LO)*k/(COSMO_OM_N-1);

const cosmoOmDepth=Om=>0.26-2.45*Math.max(0,Math.min(1,(Om-COSMO_OM_LO)/(COSMO_OM_HI-COSMO_OM_LO)));

const cosmoMu=(z,H0,Om,n)=>{ const Or=9.182e-5, OL=1-Om-Or;
  const DL=cosmoComoving(z,H0,Om,Or,OL,n||600)*(1+z);
  return 5*Math.log10(Math.max(1e-12,DL)*1e6/10); };

const cosmoMuGap=(z,H0,OmA,OmB,n)=>cosmoMu(z,H0,OmA,n)-cosmoMu(z,H0,OmB,n);

const cosmoHubbleDistance=H0=>COSMO_C/H0;

const cosmoComoving=(z,H0,Om,Or,OL,n)=>cosmoHubbleDistance(H0)
  *cosmoSimpson(x=>1/cosmoE(x,Om,Or,OL),0,z,n||2000);

const cosmoLookback=(z,H0,Om,Or,OL,n)=>(COSMO_GYR_PER_INVH/H0)
  *cosmoSimpson(x=>1/((1+x)*cosmoE(x,Om,Or,OL)),0,z,n||2000);

const cosmoAge=(H0,Om,Or,OL,n)=>(COSMO_GYR_PER_INVH/H0)
  *cosmoSimpson(u=>{ const z=u/(1-u), w=1-u;
      return 1/((1+z)*cosmoE(z,Om,Or,OL)*w*w); },0,0.999999,n||20000);

function cosmoAngularPeak(H0,Om,Or,OL){
  let bz=0,bd=0;
  for(let z=0.2;z<4;z+=0.01){ const d=cosmoComoving(z,H0,Om,Or,OL,400)/(1+z);
    if(d>bd){ bd=d; bz=z; } }
  /* one golden refinement pass so the reported redshift is not the grid step */
  let lo=bz-0.01, hi=bz+0.01;
  for(let i=0;i<40;i++){ const m1=lo+(hi-lo)*0.382, m2=lo+(hi-lo)*0.618;
    const d1=cosmoComoving(m1,H0,Om,Or,OL,400)/(1+m1), d2=cosmoComoving(m2,H0,Om,Or,OL,400)/(1+m2);
    if(d1<d2) lo=m1; else hi=m2; }
  const z=(lo+hi)/2;
  return {z, D_A:cosmoComoving(z,H0,Om,Or,OL,2000)/(1+z)};
}

const JEANS_G=6.67430e-11, JEANS_KB=1.380649e-23, JEANS_MH=1.67262192369e-27;

