function dLadChain(rungs){
  const R=rungs||DL_RUNGS;
  let rand=0, sys=0;
  const steps=[];
  for(const r of R){
    rand=Math.hypot(rand,r.sigma_mag);
    sys+=r.systematic_mag;
    steps.push({id:r.id, cumulative_random_mag:rand, cumulative_systematic_mag:sys,
      cumulative_distance_error:dLadMagnitudesToFraction(Math.hypot(rand,sys)),
      reach_pc:r.reach_pc});
  }
  return {steps, random_mag:rand, systematic_mag:sys,
    total_mag:Math.hypot(rand,sys),
    total_fraction:dLadMagnitudesToFraction(Math.hypot(rand,sys))};
}

