  return Math.exp(a)/Math.sqrt(a)*(0.39894228+y*(0.1328592e-1+y*(0.225319e-2+y*(-0.157565e-2
    +y*(0.916281e-2+y*(-0.2057706e-1+y*(0.2635537e-1+y*(-0.1647633e-1+y*0.392377e-2))))))));
