const XP_YR=365.25*XP_DAY;

const XP_G=6.67430e-11;

const XP_GMSUN=1.32712440018e20;

const XP_MSUN_IMPLIED=XP_GMSUN/XP_G;

const XP_LSUN=3.828e26;

const XP_TSUN=5772;

const XP_SIGMA=5.670374419e-8;

const xpDepth=(rp,rs)=>{ const q=rp/rs; return q*q; };

const xpSemiMajor=(P,gm)=>Math.cbrt(gm*P*P/(4*Math.PI*Math.PI));

const xpPeriod=(a,gm)=>2*Math.PI*Math.sqrt(a*a*a/gm);

function xpDuration(P,a,rs,rp,b){
  const bb=(b||0)*rs;
  const x=(rs+rp)*(rs+rp)-bb*bb;
  if(!(x>0)) return 0;                       /* it misses: there is no transit */
  const s=Math.sqrt(x)/a;
  if(s>=1) return P/2;
  return (P/Math.PI)*Math.asin(s); }

const xpTransitProbability=(rs,rp,a)=>Math.min(1,(rs+rp)/a);

function xpRadialVelocity(P,mp,ms,inc,ecc){
  const i=(inc==null)?Math.PI/2:inc;
  const e=ecc||0;
  return Math.cbrt(2*Math.PI*XP_G/P)*mp*Math.sin(i)
       / Math.cbrt((ms+mp)*(ms+mp)) / Math.sqrt(1-e*e); }

const xpEquilibriumT=(ts,rs,a,albedo)=>ts*Math.sqrt(rs/(2*a))*Math.pow(1-(albedo||0),0.25);

const xpLuminosity=(rs,ts)=>4*Math.PI*rs*rs*XP_SIGMA*ts*ts*ts*ts;

const XP_HZ=Object.freeze({recentVenus:0.75, runawayGreenhouse:0.97,
                           maxGreenhouse:1.70, earlyMars:1.77});

function xpHabitableZone(lum){
  const s=Math.sqrt(lum/XP_LSUN);
  return {recent_venus:XP_HZ.recentVenus*s, inner:XP_HZ.runawayGreenhouse*s,
          outer:XP_HZ.maxGreenhouse*s, early_mars:XP_HZ.earlyMars*s, scale:s}; }

function xpZoneStanding(aAU,hz){
  return {recent_venus:aAU>=hz.recent_venus, conservative:aAU>=hz.inner&&aAU<=hz.outer,
          optimistic:aAU>=hz.recent_venus&&aAU<=hz.early_mars,
          too_hot:aAU<hz.recent_venus, too_cold:aAU>hz.early_mars}; }

const xpInZone=(aAU,hz)=>aAU>=hz.inner&&aAU<=hz.outer;

const xpFluxEarth=(lum,aAU)=>(lum/XP_LSUN)/(aAU*aAU);

