function windLifetimeWith(lum,m0,f){
  const fuel=HR_EPS*HR_FCORE*m0;
  const N=8000, dt=Math.max(1,(HR_EPS*HR_FCORE*m0*HR_MSUN*HR_C*HR_C/(lum(m0)*HR_LSUN)/WIND_YR)*2/N);
  let m=m0, burned=0, t=0, n=0;
  while(burned<fuel && n<N*4 && m>0.08){
    const L=lum(m); if(!(L>0)) break;
    burned+=L*WIND_LSUN*dt*WIND_YR/(WIND_MSUN*WIND_C*WIND_C);
    m-=f*L*WIND_LSUN/(WIND_C*windTerminalSpeed(m,hrRadius(m)))*WIND_YR/WIND_MSUN*dt;
    t+=dt; n++;
  }
  const naive=HR_EPS*HR_FCORE*m0*HR_MSUN*HR_C*HR_C/(lum(m0)*HR_LSUN)/WIND_YR;
  return (naive>0)?t/naive:null;
}

const PHI_R=(1+Math.sqrt(5))/2;

const edgeMu   =l=>2*l+1;

const edgeBr   =(l,q)=>(l*(l+1)<=q?1:0);

const edgeAPS  =(l,C)=>C/(l+1);

