function edgeNaiveRoot(C){
  const f=N=>N*Math.log(PHI_R)-Math.log(N*N+C);
  let lo=1.5,hi=400; if(f(lo)*f(hi)>0) return NaN;
  for(let i=0;i<300;i++){ const m=(lo+hi)/2; (f(lo)*f(m)<=0?hi=m:lo=m); }
  return (lo+hi)/2;
}

